import grpc
from concurrent import futures
import os
import logging

import file_service_pb2
import file_service_pb2_grpc

logger = logging.getLogger(__name__)

class FileServiceServicer(file_service_pb2_grpc.FileServiceServicer):
    """gRPC service for reading configuration and log files."""

    BASE_DIR = "/app/data"

    def ReadFile(self, request, context):
        """Read a file relative to the base data directory."""
        file_path = request.path

        # Basic validation - reject null bytes
        if '\x00' in file_path:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details('Invalid path')
            return file_service_pb2.FileResponse(content=b'', error='Invalid path')

        # Normalize and construct full path
        # Note: we intentionally use os.path.join which does NOT prevent traversal
        # when the user input starts with relative components like ../
        full_path = os.path.join(self.BASE_DIR, file_path)

        # This check is bypassable: os.path.normpath resolves symlinks differently
        # than the actual filesystem access
        normalized = os.path.normpath(full_path)

        logger.info(f"File read request: {file_path} -> resolved: {normalized}")

        try:
            with open(normalized, 'rb') as f:
                content = f.read(1024 * 1024)  # 1MB max
            return file_service_pb2.FileResponse(content=content, error='')
        except FileNotFoundError:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            context.set_details(f'File not found: {file_path}')
            return file_service_pb2.FileResponse(content=b'', error='Not found')
        except PermissionError:
            context.set_code(grpc.StatusCode.PERMISSION_DENIED)
            context.set_details('Permission denied')
            return file_service_pb2.FileResponse(content=b'', error='Permission denied')
        except Exception as e:
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details(str(e))
            return file_service_pb2.FileResponse(content=b'', error=str(e))

    def WriteFile(self, request, context):
        """Write content to a file for caching purposes."""
        file_path = request.path
        content = request.content

        # Construct target path
        full_path = os.path.join(self.BASE_DIR, file_path)
        normalized = os.path.normpath(full_path)

        logger.info(f"File write request: {file_path} -> resolved: {normalized}")

        try:
            os.makedirs(os.path.dirname(normalized), exist_ok=True)
            with open(normalized, 'wb') as f:
                f.write(content)
            return file_service_pb2.WriteResponse(success=True, error='')
        except OSError as e:
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details(f'Write failed: {str(e)}')
            return file_service_pb2.WriteResponse(success=False, error=str(e))

    def ListFiles(self, request, context):
        """List files in a directory."""
        dir_path = request.path
        full_path = os.path.join(self.BASE_DIR, dir_path)
        normalized = os.path.normpath(full_path)

        try:
            entries = os.listdir(normalized)
            return file_service_pb2.ListResponse(files=entries, error='')
        except Exception as e:
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details(str(e))
            return file_service_pb2.ListResponse(files=[], error=str(e))


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    file_service_pb2_grpc.add_FileServiceServicer_to_server(
        FileServiceServicer(), server
    )
    server.add_insecure_port('[::]:50051')
    logger.info('Starting gRPC FileService on port 50051')
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    serve()
